# =========================================================================
# 6. INGESTION & DATASET COMPILATION PIPELINE
# =========================================================================
def run_ingestion():
    print("Ingesting Week 06 data across webapp and root databases...")

    # A. Build Varsity Bank
    # Varsity has Pure Varsity (48) + Shared Repeats (24) = 72 items
    varsity_w6 = list(PURE_VARSITY)
    for q in SHARED_REPEATS:
        q_copy = dict(q)
        q_copy["track"] = "varsity"
        varsity_w6.append(q_copy)

    # B. Build Medical Bank
    # Medical has Pure Medical (24) + Shared Repeats (24) = 48 items
    medical_w6 = list(PURE_MEDICAL)
    for q in SHARED_REPEATS:
        q_copy = dict(q)
        q_copy["track"] = "medical"
        medical_w6.append(q_copy)

    # C. Build Union Quizzes / Questions
    # 48 pure var + 24 shared + 24 pure med = 96 items
    all_w6_map = {}
    for q in PURE_VARSITY:
        all_w6_map[q["id"]] = q
    for q in SHARED_REPEATS:
        all_w6_map[q["id"]] = q
    for q in PURE_MEDICAL:
        all_w6_map[q["id"]] = q
    all_w6 = list(all_w6_map.values())

    print(f"Counts: Varsity W6={len(varsity_w6)}, Medical W6={len(medical_w6)}, Union W6={len(all_w6)}")

    # Update Varsity Bank
    for vpath in [
        os.path.join(DATA_DIR, "varsity_bank.json"),
        os.path.join(BASE_DIR, "varsity_bank.json")
    ]:
        if os.path.exists(vpath):
            with open(vpath, "r", encoding="utf-8") as f:
                data = json.load(f)
            # Remove existing week_06 items if any
            data = [item for item in data if item.get("week_id") != "week_06"]
            data.extend(varsity_w6)
            with open(vpath, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            print(f"Updated {vpath} (Total items: {len(data)})")

    # Update Medical Bank
    for mpath in [
        os.path.join(DATA_DIR, "medical_bank.json"),
        os.path.join(BASE_DIR, "medical_bank.json")
    ]:
        if os.path.exists(mpath):
            with open(mpath, "r", encoding="utf-8") as f:
                data = json.load(f)
            data = [item for item in data if item.get("week_id") != "week_06"]
            data.extend(medical_w6)
            with open(mpath, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            print(f"Updated {mpath} (Total items: {len(data)})")

    # Update Quizzes and Questions
    for qpath in [
        os.path.join(DATA_DIR, "quizzes.json"),
        os.path.join(DATA_DIR, "questions.json"),
        os.path.join(BASE_DIR, "questions.json")
    ]:
        if os.path.exists(qpath):
            with open(qpath, "r", encoding="utf-8") as f:
                data = json.load(f)
            data = [item for item in data if item.get("week_id") != "week_06"]
            data.extend(all_w6)
            with open(qpath, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            print(f"Updated {qpath} (Total items: {len(data)})")

    # Update weeks.json
    weeks_path = os.path.join(DATA_DIR, "weeks.json")
    if os.path.exists(weeks_path):
        with open(weeks_path, "r", encoding="utf-8") as f:
            weeks_data = json.load(f)
        weeks_data = [w for w in weeks_data if w.get("id") != "week_06"]
        weeks_data.append({
            "id": "week_06",
            "name": "Week 06",
            "badge": "তাপ ও পর্যায়বৃত্ত গতি, পরিবেশ ও তড়িৎ রসায়ন, ত্রিকোণমিতি ও দ্বিপদী, পরিপাক ও রেচন",
            "description": "৮০/২০ হাই-ইল্ড মাল্টি-স্ট্রিম কোর: তাপগতিবিদ্যা ও SHM, ভ্যান ডার ওয়ালস ও নার্নস্ট সমীকরণ, ত্রিকোণমিতিক রূপান্তর ও দ্বিপদী বিস্তৃতি, মানব শারীরতত্ত্ব ও অণুজীব।",
            "subjects": [
                "Physics",
                "Chemistry",
                "Higher Math",
                "Biology",
                "English",
                "GK"
            ],
            "total_mcqs": len(all_w6),
            "total_slides": 16,
            "total_flashcards": 60
        })
        with open(weeks_path, "w", encoding="utf-8") as f:
            json.dump(weeks_data, f, ensure_ascii=False, indent=2)
        print(f"Updated {weeks_path} with Week 06 metadata.")

    # Update predictor_sets.json with Week 06 prediction sets & written problems
    pred_path = os.path.join(DATA_DIR, "predictor_sets.json")
    pred_root_path = os.path.join(BASE_DIR, "predictor_sets.json")
    for pfile in [pred_path, pred_root_path]:
        if os.path.exists(pfile):
            with open(pfile, "r", encoding="utf-8") as f:
                psets = json.load(f)
            
            # Check if Week 06 varsity set already exists
            vsets = psets.get("varsity_sets", [])
            vsets = [s for s in vsets if s.get("id") != "var_pred_set_06"]
            vsets.append({
                "id": "var_pred_set_06",
                "title": "🎯 DU 'Ka' Week 06 80/20 Multi-Stream Master Prediction Set",
                "track": "varsity",
                "duration_minutes": 60,
                "total_marks": 100,
                "negative_marking": 0.25,
                "badge": "Week 06 Master 80/20",
                "description": "তাপগতিবিদ্যা ও SHM, পরিবেশ ও তড়িৎ রসায়ন, ত্রিকোণমিতি ও দ্বিপদী বিস্তৃতি এবং পরিপাক-রেচন সমন্বয়ে গঠিত পূর্ণাঙ্গ মডেল সেট।",
                "syllabus_scope": "Week 06 Full 80/20 Core Syllabus",
                "subjects": ["Physics", "Chemistry", "Higher Math", "Biology"],
                "target_mcqs": 60,
                "written_included": True,
                "written_problems": DU_WRITTEN_SPECIALS
            })
            psets["varsity_sets"] = vsets

            msets = psets.get("medical_sets", [])
            msets = [s for s in msets if s.get("id") != "med_pred_set_06"]
            msets.append({
                "id": "med_pred_set_06",
                "title": "🩺 Medical Week 06 80/20 Multi-Stream Master Prediction Set",
                "track": "medical",
                "duration_minutes": 60,
                "total_marks": 100,
                "negative_marking": 0.25,
                "badge": "Week 06 MAT Master 80/20",
                "description": "গাজী আজমল ও আবুল হাসান স্যারের পাঠ্যবইয়ের প্রত্যক্ষ লাইন, ব্যতিক্রম ম্যাট্রিক্স, ইংরেজি ইনভার্শন ও মুক্তিযুদ্ধ-সংবিধান জিকে সমন্বিত মডেল টেস্ট।",
                "syllabus_scope": "Week 06 Medical Core Syllabus",
                "subjects": ["Biology", "Chemistry", "Physics", "English", "GK"],
                "target_mcqs": 60,
                "written_included": False
            })
            psets["medical_sets"] = msets

            with open(pfile, "w", encoding="utf-8") as f:
                json.dump(psets, f, ensure_ascii=False, indent=2)
            print(f"Updated {pfile} with Week 06 prediction sets.")

    # Update vault.json
    vault_path = os.path.join(DATA_DIR, "vault.json")
    if os.path.exists(vault_path):
        with open(vault_path, "r", encoding="utf-8") as f:
            vault_data = json.load(f)
        
        entries = vault_data.get("entries", [])
        existing_v_ids = set(e["id"] for e in entries)
        for ventry in WEEK_06_VAULT_ENTRIES:
            if ventry["id"] in existing_v_ids:
                entries = [e for e in entries if e["id"] != ventry["id"]]
            entries.append(ventry)
        vault_data["entries"] = entries
        
        with open(vault_path, "w", encoding="utf-8") as f:
            json.dump(vault_data, f, ensure_ascii=False, indent=2)
        print(f"Updated {vault_path} with Week 06 vault entries (Total: {len(entries)}).")

if __name__ == "__main__":
    run_ingestion()
